import sqlite3

class ProductAPI:
    def __init__(self):
        self.connection = sqlite3.connect(':memory:')
        self.cursor = self.connection.cursor()
        self.setup_db()

    def setup_db(self):
        self.cursor.execute('''CREATE TABLE products (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            price REAL NOT NULL
        )''')
        self.cursor.execute('''INSERT INTO products (name, price) VALUES (?, ?)''', ('Laptop', 999.99))
        self.connection.commit()

    def get_products(self, page=1, per_page=10):
        offset = (page - 1) * per_page
        query = '''SELECT id, name, price FROM products LIMIT ? OFFSET ?'''
        self.cursor.execute(query, (per_page, offset))
        return self.cursor.fetchall()

    def close_connection(self):
        self.connection.close()

